    "V": [
      "Arrhythmia (e.g., SVT, atrial fibrillation): Paroxysmal palpitations, episodic shortness of breath and sensation of rapid heartbeat could represent supraventricular tachycardia or other arrhythmia causing symptomatic episodes at rest."
    ],
    "I": [
      "Subacute thyroiditis (inflammatory): Thyroid inflammation can cause transient thyrotoxicosis with palpitations, heat intolerance, weight loss and headache-like symptoms; fits with known thyroid history and current systemic symptoms."
    ],
    "N": [
      "Intracranial mass or space-occupying lesion: New-onset persistent frontal headaches with nausea could, less likely, reflect an intracranial process—though pattern (episodic, work-related) argues against this as primary cause."
    ],
    "D": [
      "Vitamin B12 deficiency or other nutritional deficiency: Can cause paresthesias (bilateral hand tingling) and neuropsychiatric symptoms; however onset and systemic adrenergic symptoms are not typical."
    ],
    "I2": [
      "Iatrogenic thyrotoxicosis from excess levothyroxine: Patient is on thyroxine and has classic hyperthyroid symptoms (palpitations, heat intolerance, weight loss, decreased libido, anxiety-like symptoms); overreplacement is a likely iatrogenic cause.",
      "Caffeine or stimulant excess / medication side effect: Episodic palpitations, anxiety, tremor and headaches can be caused or worsened by stimulants (not reported by patient but worth considering)."
    ],
    "C": [
      "Congenital arrhythmia substrate (e.g., WPW): A structural/ electrical congenital predisposition could cause paroxysmal palpitations in a younger adult, though no prior history reported."
    ],
    "A": [
      "Graves' disease (autoimmune hyperthyroidism): An autoimmune cause of thyrotoxicosis could explain systemic sympathetic symptoms, weight loss and libido changes; relevant given thyroid history though no eye signs mentioned."
    ],
    "T": [
      "Cervical or postural strain from computer work: Repetitive posture and neck strain can cause frontal headaches and may be associated with paresthesias in the hands due to nerve irritation or radiculopathy."
    ],
    "E": [
      "Primary thyrotoxicosis (toxic adenoma / Graves / toxic multinodular goitre): Fits the systemic sympathetic symptoms (heat intolerance, palpitations, weight loss, decreased libido); endocrine causes should be evaluated with thyroid function tests.",
      "Pheochromocytoma: Paroxysmal headaches, palpitations, sweating/feeling hot and weight loss are features of catecholamine-secreting tumours—rare but can produce episodic symptoms similar to those described."
    ]
  },
